        - model
        - context_tokens
        - context_limit_tokens
      title: ContextUsageContextUsageEvent
    ContextUsage:
      type: object
      properties:
        context_usage_event:
          $ref: '#/components/schemas/ContextUsageContextUsageEvent'
        type:
          type: string
          enum:
            - context_usage
